package com.basiclab.iot.transform.channel.party;
import com.basiclab.iot.transform.core.envelope.TransformEnvelope; import com.basiclab.iot.transform.core.spi.PartyConnector; import com.fasterxml.jackson.databind.ObjectMapper; import java.net.URI; import java.net.http.*; import java.time.Duration; import java.util.Map;
abstract class RestPartyConnector implements PartyConnector { private final HttpClient client; private final ObjectMapper mapper; RestPartyConnector(HttpClient c,ObjectMapper m){client=c;mapper=m;} public void validate(Map<String,Object> c){if(c.get("endpoint")==null)throw new IllegalArgumentException("contract endpoint is required");} public void deliver(Map<String,Object> c,TransformEnvelope e)throws Exception{validate(c);HttpResponse<Void> r=client.send(HttpRequest.newBuilder(URI.create(c.get("endpoint").toString())).timeout(Duration.ofSeconds(10)).header("Content-Type","application/json").header("X-Transform-Event-Id",e.getEventId()).POST(HttpRequest.BodyPublishers.ofString(mapper.writeValueAsString(e))).build(),HttpResponse.BodyHandlers.discarding());if(r.statusCode()<200||r.statusCode()>=300)throw new IllegalStateException("party returned "+r.statusCode());} }
